import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as t,af as e}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Gemini 全家族术语表","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/gemini/gemini-glossary.md","filePath":"zh/products/ai-coding/gemini/gemini-glossary.md","lastUpdated":1787042982000}'),a={name:"zh/products/ai-coding/gemini/gemini-glossary.md"};function r(i,n,p,l,g,c){return t(),s("div",null,[...n[0]||(n[0]=[e(`<h1 id="gemini-全家族术语表" tabindex="-1">Gemini 全家族术语表 <a class="header-anchor" href="#gemini-全家族术语表" aria-label="Permalink to &quot;Gemini 全家族术语表&quot;">​</a></h1><blockquote><p>这份文档解释 Gemini 全家族里的<strong>概念</strong>：它是什么、为什么存在、在生态里扮演什么角色、和相邻概念的区别。</p><p>要查命令、配置键、订阅数字，去 <a href="./gemini-cheatsheet.html">速查表</a>；要照场景抄配方，去 <a href="./gemini-cookbook.html">Cookbook</a>。</p></blockquote><h2 id="概念关系图" tabindex="-1">概念关系图 <a class="header-anchor" href="#概念关系图" aria-label="Permalink to &quot;概念关系图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                        ┌─────────────────────────────┐</span></span>
<span class="line"><span>                        │      Agent-first 范式        │</span></span>
<span class="line"><span>                        │ AI 是行动者，不是补全引擎     │</span></span>
<span class="line"><span>                        └──────────────┬──────────────┘</span></span>
<span class="line"><span>                                       │ 落地为</span></span>
<span class="line"><span>        ┌──────────────────────────────┼──────────────────────────────┐</span></span>
<span class="line"><span>        │                              │                              │</span></span>
<span class="line"><span> ┌──────▼──────┐               ┌───────▼───────┐              ┌───────▼───────┐</span></span>
<span class="line"><span> │  Gemini CLI │               │  Antigravity  │              │     Jules     │</span></span>
<span class="line"><span> │   终端本地   │               │  本地多表面    │              │    云端 VM    │</span></span>
<span class="line"><span> └──────┬──────┘               └───────┬───────┘              └───────┬───────┘</span></span>
<span class="line"><span>        │                              │                              │</span></span>
<span class="line"><span>   约束与记忆                      约束与能力                      约束与产出</span></span>
<span class="line"><span>        │                              │                              │</span></span>
<span class="line"><span> ┌──────▼──────────┐    ┌──────────────▼──────────────┐    ┌──────────▼────────┐</span></span>
<span class="line"><span> │ GEMINI.md 项目  │    │ Rules 规则（全局 + 工作区）   │    │ AGENTS.md 仓库指令 │</span></span>
<span class="line"><span> │ system.md 系统  │    │ Skill 技能（目录 + SKILL.md） │    │ Pull Request 交付  │</span></span>
<span class="line"><span> │ Extension 扩展  │    │ Workflow 工作流（/名字调用）  │    └───────────────────┘</span></span>
<span class="line"><span> └──────┬──────────┘    │ Subagent 子智能体（并发）     │</span></span>
<span class="line"><span>        │               │ Artifact 构件（可审查中间物）  │</span></span>
<span class="line"><span>        │               └──────────────┬──────────────┘</span></span>
<span class="line"><span>        │                              │</span></span>
<span class="line"><span>        └───────────┬──────────────────┘</span></span>
<span class="line"><span>                    │ 都通过</span></span>
<span class="line"><span>            ┌───────▼────────┐</span></span>
<span class="line"><span>            │      MCP       │  接外部工具（GitHub / 浏览器 / 数据库）</span></span>
<span class="line"><span>            └────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  横向的安全与可恢复机制：</span></span>
<span class="line"><span>  Trusted Folder（信任才加载项目配置） · Checkpoint（改动前存档，可回滚）</span></span>
<span class="line"><span>  Session（整段对话可列出与恢复） · Headless Mode（一次性执行，进管道）</span></span></code></pre></div><p>一句话读法：<strong>范式（Agent-first）决定了产品形态（CLI / Antigravity / Jules），产品形态决定了你用什么载体去约束它（GEMINI.md / Rules / AGENTS.md），而 MCP 决定了它能碰到多大的世界。</strong></p><h2 id="agent-first" tabindex="-1">Agent-first <a class="header-anchor" href="#agent-first" aria-label="Permalink to &quot;Agent-first&quot;">​</a></h2><p><strong>是什么</strong>：一种产品设计前提——假设 AI 是能自主规划、调用工具、执行多步任务的行动者，而不是等你敲一半代码再补全后半截的引擎。</p><p><strong>为什么需要这个概念</strong>：它解释了 Antigravity 为什么不是&quot;又一个装了 AI 的编辑器&quot;。补全式工具的交互单位是&quot;一次按键&quot;，Agent-first 工具的交互单位是&quot;一个任务&quot;。这直接改变了你该给它什么输入：补全工具需要光标位置，智能体需要目标、约束和验收标准。</p><p><strong>生态角色</strong>：这是整个 Gemini 编码家族的共同前提。Gemini CLI 在终端里体现它，Antigravity 在桌面端体现它，Jules 在云端体现它。</p><p><strong>与&quot;AI 补全&quot;的区别</strong>：补全在你的编辑循环内部；智能体自己拥有一个编辑循环。前者出错你立刻看见，后者出错可能在二十个文件之后才暴露——这就是 <a href="#checkpoint-检查点">Checkpoint</a> 和 <a href="#artifact-构件">Artifact</a> 存在的原因。</p><p><strong>官方文档</strong>：<a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity 文档首页</a></p><h2 id="surface-表面" tabindex="-1">Surface 表面 <a class="header-anchor" href="#surface-表面" aria-label="Permalink to &quot;Surface 表面&quot;">​</a></h2><p><strong>是什么</strong>：Antigravity 的多个入口。官方把桌面应用、CLI（终端 UI）、SDK（Python）、IDE 集成描述为构建在<strong>同一套智能体 harness</strong> 之上的不同表面。</p><p><strong>为什么需要这个概念</strong>：它回答了一个很常见的困惑——&quot;我在桌面端配的规则，用 CLI 还生效吗？&quot;因为共享同一套 harness，规则、技能这类约束是跨表面的，你只需要按当下的工作方式挑入口，而不用重新学一套心智模型。</p><p><strong>工作机制</strong>：表面负责交互形态（图形界面 / 终端 / 编程接口），harness 负责智能体的规划、工具调用与执行。</p><p><strong>与&quot;多客户端&quot;的区别</strong>：普通多客户端往往只是同一个后端 API 的不同壳子，能力常常不对等；表面共享的是智能体运行时本身。</p><p><strong>使用场景</strong>：交互式探索用桌面端；接进已有脚本用 CLI；要把智能体嵌入自己的自动化流程用 SDK。</p><p><strong>官方文档</strong>：<a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity 文档首页</a></p><h2 id="rules-规则" tabindex="-1">Rules 规则 <a class="header-anchor" href="#rules-规则" aria-label="Permalink to &quot;Rules 规则&quot;">​</a></h2><p><strong>是什么</strong>：长期生效的行为约束文件。Antigravity 分两级——全局规则在 <code>~/.gemini/GEMINI.md</code>，工作区规则在 <code>.agents/rules</code> 目录。官方明确每个规则文件上限 12,000 字符。</p><p><strong>为什么需要</strong>：智能体每次任务都从零开始理解你的偏好，成本极高且不稳定。规则把&quot;我们用 pnpm 不用 npm&quot;&quot;所有组件必须带类型&quot;这类不变量沉淀下来，不必每次重述。</p><p><strong>工作机制</strong>：官方提供四种激活模式——Manual（手动引用）、Always On（始终加载）、Model Decision（模型判断是否需要）、Glob（按文件模式匹配触发）。规则之间可以用 <code>@filename</code> 交叉引用。</p><p><strong>与 <a href="#skill-技能">Skill 技能</a> 的区别</strong>：规则是&quot;你必须始终这样做&quot;（约束），技能是&quot;遇到这类活儿按这个流程做&quot;（能力）。约束总是在场，能力按需加载。</p><p><strong>与 Gemini CLI 的 <code>GEMINI.md</code> 的区别</strong>：作用相同（提供长期上下文），但位置与分层机制不同，别把两者的路径混着写。</p><p><strong>使用场景</strong>：编码规范、技术栈约束、禁止事项、评审清单。</p><p><strong>官方文档</strong>：<a href="https://antigravity.google/docs/rules-workflows" target="_blank" rel="noreferrer">Rules &amp; Workflows</a></p><h2 id="skill-技能" tabindex="-1">Skill 技能 <a class="header-anchor" href="#skill-技能" aria-label="Permalink to &quot;Skill 技能&quot;">​</a></h2><p><strong>是什么</strong>：一个<strong>目录</strong>，里面放一个 <code>SKILL.md</code>。位置是 <code>.agents/skills/&lt;folder&gt;/SKILL.md</code>（随仓库走）或 <code>~/.gemini/config/skills/&lt;folder&gt;/SKILL.md</code>（全局）。frontmatter 里 <code>description</code> 必填，<code>name</code> 可选。</p><p><strong>为什么需要</strong>：把专项流程（比如&quot;怎么给这个项目发版&quot;&quot;怎么写这套 E2E 测试&quot;）从一次性提示词变成可复用、可提交进仓库、可被团队共享的资产。</p><p><strong>工作机制</strong>：<code>description</code> 是模型判断&quot;这个技能现在用不用得上&quot;的依据，所以它要写得像触发条件而不是标题。因为技能是目录，你可以把脚本、模板、示例数据一起放进去，让 <code>SKILL.md</code> 引用它们。</p><p><strong>常见误解</strong>：技能<strong>不是</strong>一个扁平的 <code>.md</code> 文件。历史文档里 <code>.agents/skills/xxx.md</code> 这种写法是错的。<code>.agent/skills</code>（单数）仅作为向后兼容保留，新建请用 <code>.agents/skills</code>。</p><p><strong>使用场景</strong>：发版流程、代码迁移套路、领域特定的调试步骤。</p><p><strong>官方文档</strong>：<a href="https://antigravity.google/docs/skills" target="_blank" rel="noreferrer">Skills</a></p><h2 id="workflow-工作流" tabindex="-1">Workflow 工作流 <a class="header-anchor" href="#workflow-工作流" aria-label="Permalink to &quot;Workflow 工作流&quot;">​</a></h2><p><strong>是什么</strong>：可以用 <code>/&lt;workflow-name&gt;</code> 显式调用的多步流程。</p><p><strong>为什么需要</strong>：有些流程你希望<strong>由人决定何时开始</strong>，而不是让模型自己判断。技能靠 description 被动匹配，工作流靠斜杠命令主动触发。</p><p><strong>与 <a href="#skill-技能">Skill 技能</a> 的区别</strong>：触发权归属不同——技能是模型决定要不要用，工作流是你决定什么时候跑。</p><p><strong>使用场景</strong>：上线前检查、生成周报、固定格式的代码审查。</p><p><strong>官方文档</strong>：<a href="https://antigravity.google/docs/rules-workflows" target="_blank" rel="noreferrer">Rules &amp; Workflows</a></p><h2 id="subagent-子智能体" tabindex="-1">Subagent 子智能体 <a class="header-anchor" href="#subagent-子智能体" aria-label="Permalink to &quot;Subagent 子智能体&quot;">​</a></h2><p><strong>是什么</strong>：主智能体派出去干活的下级智能体。Antigravity 官方把它描述为 Asynchronous Subagents（异步子智能体）。</p><p><strong>为什么需要</strong>：单个智能体的上下文窗口是有限资源。让子智能体各自去读一个模块、各自返回结论，主智能体只消费结论而不消费原始文件，能在同样的窗口里处理大得多的任务。</p><p><strong>工作机制</strong>：子智能体独立执行、异步返回。这意味着主智能体在等结果的同时可以继续推进别的分支。</p><p><strong>代价</strong>：并发意味着改动来自多个方向，冲突与&quot;两个子智能体改了同一个文件&quot;的风险变高。这也是 <a href="#artifact-构件">Artifact 构件</a> 有价值的原因——你需要能审查它们各自打算做什么。</p><p><strong>官方文档</strong>：<a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity 文档首页</a></p><h2 id="artifact-构件" tabindex="-1">Artifact 构件 <a class="header-anchor" href="#artifact-构件" aria-label="Permalink to &quot;Artifact 构件&quot;">​</a></h2><p><strong>是什么</strong>：智能体在执行过程中产出的可审查中间产物，比如计划、任务清单、验证记录。</p><p><strong>为什么需要</strong>：智能体自主性越高，&quot;它到底打算干什么&quot;就越不透明。构件把黑箱中间态变成你可以读、可以否决的东西——这是自主性的配套刹车，不是装饰。</p><p><strong>生态角色</strong>：它和 Jules&quot;先出计划待人工批准&quot;是同一个设计动机在不同产品里的体现：<strong>在动手之前先给人一个否决点</strong>。</p><p><strong>使用场景</strong>：跨模块重构前先读它的计划；智能体跑完后用它的验证记录判断该信多少。</p><p><strong>官方文档</strong>：<a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity 文档首页</a></p><h2 id="checkpoint-检查点" tabindex="-1">Checkpoint 检查点 <a class="header-anchor" href="#checkpoint-检查点" aria-label="Permalink to &quot;Checkpoint 检查点&quot;">​</a></h2><p><strong>是什么</strong>：Gemini CLI 在每次修改文件之前自动存档，之后可以用 <code>/restore</code> 回滚。默认<strong>关闭</strong>，需要把 <code>general.checkpointing.enabled</code> 设为 <code>true</code>。</p><p><strong>为什么需要</strong>：智能体的一次任务可能连续改十几个文件。等你发现方向错了，用 <code>git checkout</code> 会连你自己手写的改动一起丢掉。检查点提供的是&quot;回到智能体动手前那一刻&quot;这个更精准的粒度。</p><p><strong>与 Git 的区别</strong>：Git 记录的是你<strong>想留下</strong>的历史，检查点记录的是你<strong>可能想撤销</strong>的自动改动。两者互补，检查点不能替代提交。</p><p><strong>使用场景</strong>：开启后再让智能体做大范围重构。</p><p><strong>官方文档</strong>：<a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI 文档</a></p><h2 id="session-会话" tabindex="-1">Session 会话 <a class="header-anchor" href="#session-会话" aria-label="Permalink to &quot;Session 会话&quot;">​</a></h2><p><strong>是什么</strong>：一次对话的完整记录，可以列出并恢复。</p><p><strong>为什么需要</strong>：真实工作会被打断。会话让&quot;昨天那个上下文&quot;不必靠你重新粘贴一遍。</p><p><strong>工作机制</strong>：会话默认永久保留，可以用配置项自动清理——<code>general.sessionRetention.enabled</code> 开启清理，<code>maxAge</code>（如 <code>&quot;30d&quot;</code>）按时间、<code>maxCount</code> 按数量、<code>minRetention</code>（默认 <code>&quot;1d&quot;</code>）兜底最短保留期。</p><p><strong>与 <a href="#checkpoint-检查点">Checkpoint 检查点</a> 的区别</strong>：会话保存的是<strong>对话</strong>，检查点保存的是<strong>文件</strong>。恢复会话不会把代码改回去。</p><p><strong>官方文档</strong>：<a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI 文档</a></p><h2 id="headless-mode-无头模式" tabindex="-1">Headless Mode 无头模式 <a class="header-anchor" href="#headless-mode-无头模式" aria-label="Permalink to &quot;Headless Mode 无头模式&quot;">​</a></h2><p><strong>是什么</strong>：用 <code>-p</code>（prompt）参数一次性执行并直接返回结果，不进入交互界面。配合 <code>--output-format json</code> 可以拿到结构化输出。</p><p><strong>为什么需要</strong>：这是让 AI 进入既有工程管道的接口。交互式界面对人友好，对脚本不友好；无头模式让 <code>gemini</code> 变成一个普通的 Unix 命令，能被管道、CI、Git hook 调用。</p><p><strong>工作机制</strong>：标准输入进、标准输出出，所以 <code>npm run build 2&gt;&amp;1 | gemini -p &quot;分析这个报错&quot;</code> 这类写法成立。</p><p><strong>使用场景</strong>：构建失败分析、批量生成、CI 检查。</p><p><strong>官方文档</strong>：<a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI 文档</a></p><h2 id="trusted-folder-信任文件夹" tabindex="-1">Trusted Folder 信任文件夹 <a class="header-anchor" href="#trusted-folder-信任文件夹" aria-label="Permalink to &quot;Trusted Folder 信任文件夹&quot;">​</a></h2><p><strong>是什么</strong>：一个安全边界机制。开启 <code>security.folderTrust.enabled</code> 后，只有被信任的目录才会加载项目级配置；信任列表存在 <code>~/.gemini/trustedFolders.json</code>。</p><p><strong>为什么需要</strong>：<code>.gemini/settings.json</code> 和自定义命令是随仓库走的。如果你克隆了一个陌生仓库并在里面启动智能体，仓库自带的配置就有机会影响智能体行为。信任机制让&quot;我读过并认可这个仓库的配置&quot;成为一个显式动作。</p><p><strong>工作机制</strong>：未信任的目录里，项目配置与自定义命令不生效。</p><p><strong>与沙盒的区别</strong>：信任控制的是&quot;<strong>加载谁的配置</strong>&quot;，沙盒控制的是&quot;<strong>执行能碰到什么</strong>&quot;。两者解决不同的问题。</p><p><strong>官方文档</strong>：<a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI 文档</a></p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p><strong>是什么</strong>：Model Context Protocol，一个让智能体连接外部工具与数据源的开放协议。</p><p><strong>为什么需要</strong>：没有 MCP 的智能体只能读写本地文件、跑本地命令。接上 MCP 之后它能查 GitHub Issue、驱动浏览器、读数据库——能力边界从&quot;这台机器&quot;扩展到&quot;这些服务&quot;。</p><p><strong>生态角色</strong>：它是 Gemini 家族与外部世界之间的统一插头，也是 Gemini CLI、Antigravity、Code Assist 共同支持的能力。</p><p><strong>工作机制</strong>：MCP 服务器暴露一组工具，智能体在需要时调用。在 Gemini CLI 里，MCP 服务器通常通过 <a href="#extension-扩展">Extension 扩展</a> 安装。</p><p><strong>安全提示</strong>：MCP 服务器往往需要凭据（比如 GitHub token）。把凭据放进环境变量或 <code>.gemini/.env</code>，<strong>不要写进会提交进仓库的配置文件，也不要直接敲在命令行里</strong>（命令行会进 shell history）。</p><p><strong>官方文档</strong>：<a href="https://geminicli.com/docs/" target="_blank" rel="noreferrer">Gemini CLI 文档</a></p><h2 id="extension-扩展" tabindex="-1">Extension 扩展 <a class="header-anchor" href="#extension-扩展" aria-label="Permalink to &quot;Extension 扩展&quot;">​</a></h2><p><strong>是什么</strong>：Gemini CLI 的安装单元，最常见的用途是安装 MCP 服务器。安装形式是 <code>gemini extensions install &lt;git-url&gt;</code>。</p><p><strong>为什么需要</strong>：把&quot;配一个 MCP 服务器&quot;从手写 JSON 变成一条命令。</p><p><strong>工作机制</strong>：从 Git 仓库地址安装。注意仓库地址必须完整含组织名，例如官方 GitHub MCP 服务器是 <code>https://github.com/github/github-mcp-server</code>——历史文档里出现过 <code>https://github.com/github-mcp-server</code>（缺组织名）这种拼错的地址，装不上。</p><p><strong>使用场景</strong>：接 GitHub、接浏览器自动化、接内部服务。可用扩展见<a href="https://geminicli.com/extensions/" target="_blank" rel="noreferrer">官方扩展市场</a>。</p><p><strong>官方文档</strong>：<a href="https://geminicli.com/extensions/" target="_blank" rel="noreferrer">Gemini CLI 扩展</a></p><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h2><p><strong>是什么</strong>：放在<strong>仓库根目录</strong>的指令文件，Jules 会自动读取。</p><p><strong>为什么需要</strong>：Jules 在云端 VM 里独立干活，你不在旁边。它需要提前知道这个仓库怎么装依赖、怎么跑测试、有什么禁区——否则它只能猜。</p><p><strong>与 <a href="#rules-规则">Rules 规则</a>、<code>GEMINI.md</code> 的区别</strong>：三者都是&quot;给智能体的长期指令&quot;，但归属不同产品、位置不同：Jules 读仓库根的 <code>AGENTS.md</code>，Antigravity 读 <code>~/.gemini/GEMINI.md</code> 与 <code>.agents/rules</code>，Gemini CLI 读 <code>GEMINI.md</code> 与 <code>.gemini/system.md</code>。<strong>不要假设写一处能被全家族共用。</strong></p><p><strong>使用场景</strong>：写清依赖安装命令、测试命令、代码风格、不许动的目录。</p><p><strong>官方文档</strong>：<a href="https://jules.google/docs/" target="_blank" rel="noreferrer">Jules 文档</a></p><h2 id="google-flow" tabindex="-1">Google Flow <a class="header-anchor" href="#google-flow" aria-label="Permalink to &quot;Google Flow&quot;">​</a></h2><p><strong>是什么</strong>：Google 的 AI 创意工作室。用 Veo 3.1、Nano Banana、Gemini Omni 从文本 / 帧 / 素材生成并精修视频与图像。入口是 <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">labs.google/fx/tools/flow</a>。</p><p><strong>为什么需要</strong>：编码主线（CLI / Antigravity / Jules）交出的是仓库里的代码。对外讲一个功能时，前端工程师还需要成片——落地页宣传、产品演示、分镜。Flow 填的是这一段，不是另一条编码入口。</p><p><strong>生态角色</strong>：对位 Claude 家族的 Claude Design。Design 出可交接的界面原型，Flow 出可发布的影像。订阅档位同时决定 Flow 积分和 Antigravity / Jules 额度，但账本分开。</p><p><strong>与 <a href="./canvas.html">Canvas</a> 的区别</strong>：Canvas 在 Gemini 对话旁边给你一个能点的工作区，产出是交互原型。Flow 产出是视频 / 图像。要 DOM 用 Canvas，要成片用 Flow。</p><p><strong>与 Flow Music 的区别</strong>：Flow Music 在 <a href="https://www.flowmusic.app/" target="_blank" rel="noreferrer">flowmusic.app</a>，做歌和 MV。Pro 对应它自己的 Plus 档（每月 10,000 音乐积分）。<strong>两本积分不能混用</strong>。</p><p><strong>Flow Sessions</strong>：落地页上的艺术家合作计划，不是日常产品。</p><p><strong>官方文档</strong>：<a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">产品入口</a>、<a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">额度</a>。产品页见 <a href="./flow.html">Flow</a>。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./gemini-cheatsheet.html">速查表</a> — 命令、配置键、订阅层级</li><li><a href="./gemini-cookbook.html">Cookbook</a> — 按场景抄配方</li><li><a href="./index.html">学习地图</a> — 学习顺序</li></ul>`,104)])])}const q=o(a,[["render",r]]);export{f as __pageData,q as default};
